// The pure parts of the parse and description Checks against what the Go
// build answers for the same input (testdata/parse-oracle.json, generated by
// testdata/parse-oracle.go.txt at the freeze commit).
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { test } from "node:test";

import { quoteJSONString } from "../gocompat/json.ts";
import { parseStructured } from "./artifacts_structured.ts";
import { repoInput } from "./checks.testutil.ts";
import { redoclyFindings } from "./repo_findings.ts";
import { schemaHelperInput } from "./schema_compile.ts";
import {
  driftDiff,
  driftDiffArtifact,
  driftEvidence,
} from "./schema_drift_results.ts";

interface Oracle {
  parse: {
    rel: string;
    data: string | null;
    error: {
      rule: string;
      line: number;
      column: number;
      message: string;
    } | null;
  }[];
  drift: {
    rel: string;
    committed: string | null;
    generated: string | null;
    diff: string | null;
    differs: boolean;
  }[];
  artifacts: {
    context_id: string;
    rel: string;
    diff: string | null;
    id: string;
    path: string;
    content: string | null;
    content_sha256: string;
    content_size: number;
    truncated: boolean;
    evidence: string;
  }[];
  helper_inputs: {
    targets: { rel: string; data: string | null }[] | null;
    drafts: string[] | null;
    input: string;
  }[];
  redocly: {
    path: string;
    remote_ref: boolean;
    stdout: string | null;
    stderr: string | null;
    error: string;
    findings:
      | {
          rule: string;
          title: string;
          message: string;
          line: number;
          column: number;
          evidence: string;
          gate: boolean;
          severity: string;
        }[]
      | null;
  }[];
}

const oracle = JSON.parse(
  readFileSync(new URL("testdata/parse-oracle.json", import.meta.url), "utf8"),
) as Oracle;

function bytes(b64: string | null): Buffer {
  return Buffer.from(b64 ?? "", "base64");
}

test("structured files parse as in the Go build: verdict, rule, line, column and message", () => {
  assert.ok(oracle.parse.length > 100);
  for (const [i, c] of oracle.parse.entries()) {
    const got = parseStructured(c.rel, bytes(c.data));
    assert.deepEqual(got, c.error, `case ${String(i)}: ${c.rel}`);
  }
});

test("drift diffs match the Go build byte for byte", () => {
  for (const [i, c] of oracle.drift.entries()) {
    const [diff, differs] = driftDiff(
      c.rel,
      bytes(c.committed),
      bytes(c.generated),
    );
    assert.equal(differs, c.differs, `case ${String(i)}: ${c.rel}`);
    assert.equal(
      Buffer.from(diff, "latin1").toString("base64"),
      bytes(c.diff).toString("base64"),
      `case ${String(i)}: ${c.rel}`,
    );
  }
});

test("diff artifacts and their Evidence match the Go build", () => {
  const used = new Set<string>();
  const longLine =
    "+new line number that is long enough to fill the cap quickly\n";
  for (const [i, c] of oracle.artifacts.entries()) {
    const diff =
      c.diff === null
        ? longLine.repeat(40000)
        : bytes(c.diff).toString("latin1");
    const a = driftDiffArtifact(c.context_id, c.rel, diff, used);
    const what = `case ${String(i)}: ${c.rel}`;
    assert.equal(a.id, c.id, what);
    assert.equal(a.path, c.path, what);
    assert.equal(a.truncated, c.truncated, what);
    const content = Buffer.from(a.content ?? new Uint8Array());
    assert.equal(content.length, c.content_size, what);
    if (c.content_sha256 !== "") {
      assert.equal(
        createHash("sha256").update(content).digest("hex"),
        c.content_sha256,
        what,
      );
    } else {
      assert.equal(
        content.toString("base64"),
        bytes(c.content).toString("base64"),
        what,
      );
    }
    // Go 1.27's encoder writes invalid UTF-8 as the character U+FFFD, as the
    // port's encoder does for its text.
    assert.equal(
      quoteJSONString(driftEvidence(a).text, true),
      c.evidence,
      what,
    );
  }
});

test("the schema.compile helper input is Go's json.Marshal", () => {
  for (const [i, c] of oracle.helper_inputs.entries()) {
    const got = schemaHelperInput(
      (c.targets ?? []).map((t) => ({
        path: t.rel,
        draft: "draft-07",
        class: "source",
        schema: bytes(t.data),
      })),
    );
    assert.equal(
      got.toString("latin1"),
      bytes(c.input).toString("latin1"),
      `case ${String(i)}`,
    );
  }
});

test("Redocly output becomes the Go build's Findings and errors", (t) => {
  const input = repoInput(t, {});
  for (const [i, c] of oracle.redocly.entries()) {
    const what = `case ${String(i)}: ${c.path}`;
    let found;
    try {
      found = redoclyFindings(
        input,
        { path: c.path, remoteRef: c.remote_ref },
        bytes(c.stdout),
        bytes(c.stderr),
      );
    } catch (err) {
      assert.ok(err instanceof Error);
      assert.equal(err.message, c.error, what);
      continue;
    }
    assert.equal(c.error, "", what);
    assert.deepEqual(
      found.map((f) => ({
        rule: f.rule_id,
        title: f.title,
        message: f.message,
        line: f.locations[0]?.start?.line ?? 0,
        column: f.locations[0]?.start?.column ?? 0,
        evidence: f.evidence[0]?.text,
        gate: f.gate,
        severity: f.severity,
      })),
      // The Go build made every error a Gate; under execution-v2 api.lint
      // fires none, and every other field is as recorded.
      (c.findings ?? []).map((f) => ({ ...f, gate: false })),
      what,
    );
  }
});
